const test=require('node:test'),assert=require('node:assert/strict');const libs=Promise.all([import('../board-resolved-access.js'),import('../board-join-verifier.js'),import('../playground-model.js')]);
function fixture(){const board={id:'b',revision:1,population:6,cards:{'shared@1':{ports:[],capabilities:{housing:6}}},instances:[{instanceId:'a',cardId:'shared',cardRevision:1,q:0,r:0,rotation:0},{instanceId:'b',cardId:'shared',cardRevision:1,q:3,r:2,rotation:3}]};const plans=[0,40].map((x,i)=>({id:i?'tile-b':'tile-a',center:{x,z:0},hub:{x:0,z:0},ports:[{neighbor:i?'tile-a':'tile-b',x:i?-20:20,z:0}],warnings:[],placements:[{id:'macro-'+i,role:'home',x:0,z:-10,angle:0,w:14,d:14,items:[{asset:'box',x:-3,z:0}],internalPaths:[[{x:0,z:7},{x:0,z:0}]],door:{x:0,z:-3}}],paths:[{kind:'connector',width:3,points:[{x:0,z:0},{x:i?-20:20,z:0}]},{kind:'access',width:2,points:[{x:0,z:0},{x:0,z:-3}]},{kind:'courtyard',width:1.4,points:[{x:0,z:-3},{x:0,z:-10}]}]}));return {board,assembly:{plans},instanceIdByTile:{'tile-a':'a','tile-b':'b'}};}
function verifier(createJoinVerifier,board,heightAt=()=>0,obstacles=[]){return createJoinVerifier({boardId:board.id,boardRevision:board.revision,heightAt,contains:()=>true,obstacles,obstaclesComplete:true});}
test('instance overlays preserve shared empty source ports and never double-transform resolved world coordinates',async()=>{const [access,{createJoinVerifier},{inspectConnections,simulationBoard}]=await libs,f=fixture(),before=JSON.stringify(f.board),verify=verifier(createJoinVerifier,f.board),resolved=access.resolveAssemblyAccess({...f,heightAt:()=>0,verifySegment:verify});assert.equal(resolved.warnings.length,0);assert.equal(resolved.resolvedPortsByInstance.a.ports[0].x,20);assert.equal(resolved.resolvedPortsByInstance.b.ports[0].x,20);assert.equal(inspectConnections(f.board,{...resolved,verifyJoin:verify}).connections.length,1);assert.equal(simulationBoard(f.board,{...resolved,verifyJoin:verify}).connections.length,1);assert.equal(JSON.stringify(f.board),before);});
test('steep or obstructed approach blocks economy even when the shared seam is flat and clear',async()=>{const [access,{createJoinVerifier},{inspectConnections}]=await libs;for(const kind of ['hill','obstacle']){const f=fixture(),h=kind==='hill'?(x,z)=>Math.abs(z)<1?Math.max(0,3-Math.abs(x-10)):0:()=>0,obstacles=kind==='obstacle'?[{kind:'box',x:10,z:0,w:.1,d:3}]:[],verify=verifier(createJoinVerifier,f.board,h,obstacles),resolved=access.resolveAssemblyAccess({...f,heightAt:h,verifySegment:verify});assert.equal(resolved.resolvedPortsByInstance.a.ports[0].verified,false);assert.equal(inspectConnections(f.board,{...resolved,verifyJoin:verify}).connections.length,0);}});
test('missing courtyard path or missing verifier cannot validate full service access',async()=>{const [access,{createJoinVerifier}]=await libs;let f=fixture();f.assembly.plans[0].paths.pop();let result=access.resolveAssemblyAccess({...f,heightAt:()=>0,verifySegment:verifier(createJoinVerifier,f.board)});assert.equal(result.resolvedPortsByInstance.a.ports[0].verified,false);f=fixture();result=access.resolveAssemblyAccess({...f,heightAt:()=>0});assert.equal(result.resolvedPortsByInstance.a.ports[0].verified,false);});
test('stale overlays and unspecified coordinate spaces fail closed without source fallback',async()=>{const [access,{createJoinVerifier},{inspectConnections}]=await libs,f=fixture(),verify=verifier(createJoinVerifier,f.board),resolved=access.resolveAssemblyAccess({...f,heightAt:()=>0,verifySegment:verify});resolved.resolvedPortsByInstance.a.boardRevision=0;assert.equal(inspectConnections(f.board,{...resolved,verifyJoin:verify}).connections.length,0);resolved.resolvedPortsByInstance.a.boardRevision=1;resolved.resolvedPortsByInstance.a.space='local';assert.equal(inspectConnections(f.board,{...resolved,verifyJoin:verify}).connections.length,0);});
test('macro containers are flattened into item obstacles and unknown item geometry remains incomplete',async()=>{const [{resolvedAssemblyObstacles}]=await libs,f=fixture();const unknown=resolvedAssemblyObstacles(f.assembly);assert.equal(unknown.complete,false);const known=resolvedAssemblyObstacles(f.assembly,()=>({kind:'box',w:1,d:1}));assert.equal(known.complete,true);assert.equal(known.obstacles.length,2);assert.equal(known.obstacles[0].x,-3);assert.equal(known.obstacles[0].z,-10);assert(known.obstacles.every(o=>o.w===1));});
